"""Local full-length editor. Outputs join the existing Publish library."""
import argparse
import json
import math
import os
from pathlib import Path
import re
import shutil
import subprocess
import textwrap


def number(value, name, minimum=0, maximum=None):
    try:
        result = float(value)
    except (ValueError, TypeError):
        raise ValueError(f'{name} must be a number.')
    if not math.isfinite(result) or result < minimum or (maximum is not None and result > maximum):
        raise ValueError(f'{name} is outside its allowed range.')
    return result


def seconds(text):
    pieces = str(text or '0').strip().replace(',', '.').split(':')
    if len(pieces) > 3:
        raise ValueError('Use seconds or HH:MM:SS for trim and note times.')
    total = 0
    for piece in pieces:
        total = total * 60 + number(piece, 'Time')
    return total


def probe(path):
    result = subprocess.run(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(path)], capture_output=True, text=True, check=True, timeout=30)
    data = json.loads(result.stdout)
    video = next((s for s in data['streams'] if s.get('codec_type') == 'video'), None)
    if not video:
        raise ValueError('This file has no video track.')
    return float(data['format']['duration']), int(video['width']), int(video['height']), any(s.get('codec_type') == 'audio' for s in data['streams'])


def plan(source, options, info=None):
    source = Path(source).resolve()
    if not source.is_file():
        raise ValueError('Choose a video file on this PC first.')
    duration, width, height, audio = info or probe(source)
    start = seconds(options.get('start','0'))
    end = seconds(options['end']) if str(options.get('end','')).strip() else duration
    if not 0 <= start < end <= duration + 0.05:
        raise ValueError('Trim start/end must lie inside the source video.')
    if end - start > 900.05:
        raise ValueError('This full-video mode supports up to 15 minutes. Set trim start/end to choose up to 15 minutes.')
    speed = number(options.get('speed',1), 'Speed', .5, 2)
    volume = number(options.get('volume',1), 'Volume', 0, 2)
    if options.get('cc') and not all(str(options.get(k,'')).strip() for k in ('author','source_url','license_url')):
        raise ValueError('For Creative Commons, fill in the original creator, source link and license link.')
    if options.get('cc') and not options.get('permission'):
        raise ValueError('Confirm that the source license permits your intended editing and upload.')
    if options.get('cc') and any(not str(options.get(k,'')).startswith(('https://','http://')) for k in ('source_url','license_url')):
        raise ValueError('Source and license links must be http or https links.')
    ratio = min(1, (720 if options.get('resolution','720p') == '720p' else 1080)/height) if options.get('resolution') != 'Original' else 1
    width, height = max(2,int(width*ratio)//2*2), max(2,int(height*ratio)//2*2)
    result = dict(source=str(source), start=start, end=end, speed=speed, volume=volume, width=width, height=height, audio=audio, duration=(end-start)/speed)
    if result['duration'] > 900.05:
        raise ValueError('The edited output must be at most 15 minutes; shorten the range or increase speed.')
    result['notes'] = []
    for line in str(options.get('notes','')).splitlines():
        if not line.strip():
            continue
        parts = line.split('|',2)
        if len(parts) != 3:
            raise ValueError('Each text note must use: start | end | your explanation')
        a,b = seconds(parts[0]), seconds(parts[1])
        if not 0 <= a < b <= result['duration'] + .05 or not parts[2].strip():
            raise ValueError('Text note times must lie inside the edited video and contain text.')
        result['notes'].append((a,b,parts[2].strip()[:500]))
    if len(result['notes']) > 40:
        raise ValueError('Use up to 40 timed notes per video.')
    if options.get('subtitle_mode') == 'Automatic (local Whisper)' and not audio:
        raise ValueError('This source has no audio. Choose an SRT file or turn subtitles off.')
    if options.get('subtitle_mode') == 'Use SRT file' and not Path(options.get('srt') or '').is_file():
        raise ValueError('Choose an SRT subtitle file first.')
    return result


def subtitle_time(t):
    ms = max(0, round(t*1000))
    return f'{ms//3600000:02d}:{ms//60000%60:02d}:{ms//1000%60:02d},{ms%1000:03d}'


def retime_cues(cues, start, end, speed):
    out = []
    for a,b,text in cues:
        a,b = max(start,float(a)), min(end,float(b))
        text = re.sub(r'<[^>]*>', '', str(text)).strip()
        if b > a and text:
            out.append(((a-start)/speed, (b-start)/speed, text))
    return out


def read_srt(path):
    data = Path(path).read_text(encoding='utf-8-sig')
    cues = []
    for block in re.split(r'\r?\n\s*\r?\n', data.strip()):
        lines = block.splitlines()
        index = next((i for i,line in enumerate(lines) if '-->' in line), None)
        if index is None:
            continue
        a,b = lines[index].split('-->',1)
        cues.append((seconds(a),seconds(b.split()[0]),'\n'.join(lines[index+1:])))
    if not cues:
        raise ValueError('No subtitle cues found in the SRT file.')
    return cues


def write_srt(path, cues):
    Path(path).write_text('\n\n'.join(f'{i}\n{subtitle_time(a)} --> {subtitle_time(b)}\n{textwrap.fill(text,64)}' for i,(a,b,text) in enumerate(cues,1))+'\n', encoding='utf-8')


def render(source, folder, options):
    from shortsflow.hashtag_research import parse_tags, description_with_tags
    folder = Path(folder).resolve()
    settings = plan(source, options)
    folder.mkdir(parents=True, exist_ok=True)
    preview = bool(options.get('preview'))
    if preview:
        settings['end'] = min(settings['end'], settings['start']+15*settings['speed'])
        settings['duration'] = (settings['end']-settings['start'])/settings['speed']
    print('Preparing full-length video (no shorts are extracted).',flush=True)
    (folder/'edit-settings.json').write_text(json.dumps(dict(options, source=settings['source']),ensure_ascii=False,indent=2),encoding='utf-8')
    cues = []
    mode = options.get('subtitle_mode','Off')
    if mode == 'Automatic (local Whisper)':
        print('Creating subtitles locally with Whisper. This can take several minutes on CPU.',flush=True)
        audio = folder/'audio_mono.wav'
        subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-y','-ss',str(settings['start']),'-i',settings['source'],'-t',str(settings['end']-settings['start']),'-vn','-ar','16000','-ac','1',str(audio)],check=True)
        from engine.analysis import transcribe_video
        transcript = json.loads(Path(transcribe_video(str(audio),str(folder),language=options.get('language','auto'))).read_text(encoding='utf-8'))
        segments = transcript.get('segments',[])
        if options.get('caption_style') == 'Word captions':
            cues = [(w['start'],w['end'],w.get('word','')) for seg in segments for w in seg.get('words',[]) if 'start' in w and 'end' in w]
        if not cues:
            cues = [(seg['start'],seg['end'],seg.get('text','')) for seg in segments]
        cues = retime_cues(cues,0,settings['end']-settings['start'],settings['speed'])
        if not cues:
            raise ValueError('Whisper found no speech. Choose an SRT file or turn subtitles off.')
    elif mode == 'Use SRT file':
        cues = retime_cues(read_srt(options['srt']),settings['start'],settings['end'],settings['speed'])
        if not cues:
            raise ValueError('The SRT has no cues inside the selected trim range.')
    filters = [f"scale={settings['width']}:{settings['height']}",f"setpts=(PTS-STARTPTS)/{settings['speed']}",'setsar=1']
    if cues:
        write_srt(folder/'captions.srt',cues)
        filters.append("subtitles=captions.srt:force_style='FontName=Arial,FontSize=24,Outline=2,Shadow=0,MarginV=24'")
    texts = [(a,b,text) for a,b,text in settings['notes'] if a < settings['duration']]
    for i,(a,b,text) in enumerate(texts):
        (folder/f'note_{i}.txt').write_text(textwrap.fill(text,55),encoding='utf-8')
        filters.append(f"drawtext=font=Arial:textfile=note_{i}.txt:expansion=none:fontsize={max(18,round(settings['height']*.032))}:fontcolor=white:box=1:boxcolor=black@0.65:boxborderw=10:x=(w-tw)/2:y=h*0.14:enable='between(t,{a},{min(b,settings['duration'])})'")
    if str(options.get('label','')).strip():
        (folder/'label.txt').write_text(str(options['label'])[:100],encoding='utf-8')
        filters.append(f"drawtext=font=Arial:textfile=label.txt:expansion=none:fontsize={max(14,round(settings['height']*.025))}:fontcolor=white:box=1:boxcolor=black@0.5:boxborderw=6:x=20:y=14")
    cmd = ['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-y','-filter_complex_threads','1','-ss',str(settings['start']),'-i',settings['source']]
    logo = options.get('logo')
    if logo:
        if not Path(logo).is_file():
            raise ValueError('The logo file is missing.')
        cmd += ['-loop','1','-i',str(Path(logo).resolve())]
        width = max(32,round(settings['width']*.12)//2*2)
        complex_filter = '[0:v]'+','.join(filters)+f'[base];[1:v]scale={width}:-2[logo];[base][logo]overlay=W-w-20:20:shortest=1[v]'
        cmd += ['-filter_complex',complex_filter,'-map','[v]']
    else:
        cmd += ['-map','0:v:0','-vf',','.join(filters)]
    if settings['audio'] and not options.get('mute'):
        cmd += ['-map','0:a:0','-af',f"asetpts=PTS-STARTPTS,atempo={settings['speed']},volume={settings['volume']}",'-c:a','aac','-b:a','128k']
    else:
        cmd += ['-an']
    pending = folder/'full_video.partial.mp4'
    output = folder/('preview_full.mp4' if preview else 'full_video.mp4')
    cmd += ['-t',str(settings['duration']),'-r','30','-c:v','libx264','-preset','veryfast','-crf','23','-pix_fmt','yuv420p','-threads','4','-movflags','+faststart','-progress','pipe:1',str(pending)]
    print(f"Rendering {'preview' if preview else 'full video'}: {settings['duration']:.1f} seconds, {settings['width']}x{settings['height']}. Original aspect ratio preserved.",flush=True)
    log = folder/'ffmpeg.log'
    with log.open('w',encoding='utf-8') as errors:
        process = subprocess.Popen(cmd,cwd=folder,stdout=subprocess.PIPE,stderr=errors,text=True,encoding='utf-8')
        try:
            last = -1
            for line in process.stdout:
                if line.startswith('out_time_us='):
                    try:
                        percent = min(99,int(float(line.split('=',1)[1])/1e6/settings['duration']*100))
                        if percent >= last+10:
                            print(f'Rendering {percent}%',flush=True)
                            last = percent
                    except ValueError:
                        pass
            process.wait()
        finally:
            if process.poll() is None:
                process.kill()
                process.wait()
            if process.stdout is not None:
                process.stdout.close()
    if process.returncode:
        raise RuntimeError('FFmpeg failed: '+log.read_text(encoding='utf-8')[-1600:])
    os.replace(pending,output)
    if not preview:
        title = str(options.get('title') or Path(source).stem)[:100]
        desc = str(options.get('description','')).strip()[:3000]
        if options.get('cc'):
            changes = ['Subtitles' if cues else '', 'Timed explanation notes' if texts else '', 'Trim' if settings['start'] or settings['end'] < probe(source)[0]-.1 else '', 'Playback speed changed' if settings['speed'] != 1 else '']
            changes = ', '.join(x for x in changes if x) or 'Re-encoded for upload'
            desc += '\n\nSource credit\nOriginal creator: '+str(options['author'])+'\nSource: '+str(options['source_url'])+'\nLicense: '+str(options['license_url'])+'\nChanges: '+changes
        tags = parse_tags(options.get('tags',''))
        if tags:
            desc = description_with_tags(desc,tags)
        (folder/'metadata.json').write_text(json.dumps([dict(file=output.name,title=title,description=desc,tags=tags)],ensure_ascii=False,indent=2),encoding='utf-8')
        (folder/'command.json').write_text(json.dumps({'cmd':['full-editor','--source_video',str(source)]}),encoding='utf-8')
    print('Saved: '+str(output),flush=True)
    return str(output)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--source_video',required=True)
    parser.add_argument('--job_file',required=True)
    args = parser.parse_args()
    job = Path(args.job_file).resolve()
    options = json.loads(job.read_text(encoding='utf-8'))
    render(args.source_video,job.parent,options)


if __name__ == '__main__':
    main()
